        const hl = (U.id === 'lizard' ? 0.5 : 0.3) * ps, ry = pm.rotation.y, fx = Math.cos(ry) * hl, fz = -Math.sin(ry) * hl, h1 = actor.groundFn(wx + fx, wz + fz), h2 = actor.groundFn(wx - fx, wz - fz);
