        for (let i = 0; i <= segs; i++) { const t = i / segs, th = 0.5 + 1.3 * t * t; if (i) { y += Math.cos(th) * len / segs; z += Math.sin(th) * len / segs; } rach.push(new V3(0, y, z)); }
