    pvel[i * 3] = (Math.random() - 0.5) * WX.drift; pvel[i * 3 + 1] = WX.fall[0] + Math.random() * (WX.fall[1] - WX.fall[0]); pvel[i * 3 + 2] = (Math.random() - 0.5) * WX.drift;
