  guard: { ico: '🛡', n: { ru: 'Щит', en: 'Guard' } }, herd: { ico: '🦶', n: { ru: 'Топот', en: 'Stomp' } }, screech: { ico: '📢', n: { ru: 'Крик', en: 'Screech' } },
  dive: { ico: '🦅', n: { ru: 'Пике', en: 'Dive' } }, sonic: { ico: '🔊', n: { ru: 'Звук', en: 'Sonic' } }, torpedo: { ico: '🚀', n: { ru: 'Торпеда', en: 'Torpedo' } }, rend: { ico: '🦈', n: { ru: 'Рывок', en: 'Rush' } }, scent: { ico: '👃', n: { ru: 'Нюх', en: 'Scent' } },
  climb: { ico: '🌲', n: { ru: 'Лазание', en: 'Climb' } }, fly: { ico: '🪽', n: { ru: 'Взлёт', en: 'Fly' } }
