      const t = i / rows, k = 0.5 - 0.5 * Math.cos(Math.PI * t);
      for (let j = 0; j <= seg; j++) {
        const a = j / seg * 6.2832, ye = jag(a), y = lo ? ye * k : ye + (L - ye) * k, r = R(Math.min(L, Math.max(0, y)));
        pos.push(Math.cos(a) * r, y, Math.sin(a) * r); uv.push(j / seg, y / L);
      }
